import {yearChange,ratio,transform,nearest} from './math.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const colors=['#008f88','#df8048','#2e68ac','#9965b5','#b99821','#cf5c80'];let catalog=[],db={},selected,category='通膨與薪資',range='10',start='',end='',mode='default',hidden=new Set(),drawn=[],shown=[];
const fmt=v=>new Intl.NumberFormat('zh-TW',{maximumFractionDigits:2}).format(v), short=v=>{const a=Math.abs(v);return a>=1e12?(v/1e12).toFixed(1)+'兆':a>=1e9?(v/1e9).toFixed(1)+'十億':a>=1e6?(v/1e6).toFixed(1)+'百萬':a>=1e4?(v/1e3).toFixed(1)+'千':fmt(v)},freq={D:'日',W:'週',M:'月',Q:'季',A:'年'};
const statusName=c=>c.status==='pending'?'待補資料':c.status==='proxy'?'替代口徑':'已接入';
async function init(){try{const [a,b]=await Promise.all([fetch('data/catalog.json',{cache:'no-cache'}),fetch('data/history.json',{cache:'no-cache'})]);if(!a.ok||!b.ok)throw Error('資料讀取失敗');catalog=await a.json();db=await b.json();$('#updateDate').textContent='資料擷取 '+new Date(db.checked).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false});const count=Object.values(db.series).filter(s=>s.data.length).length;$('#stats').innerHTML=`<div><strong>${catalog.filter(c=>c.status!=='pending').length}</strong>圖表主題</div><div><strong>${count}</strong>歷史序列</div><div><strong>${catalog.filter(c=>c.status==='pending').length}</strong>待補項目</div>`;const id=location.hash.slice(1);selected=catalog.find(c=>c.id===id)||catalog.find(c=>c.title==='總體 CPI 與核心 CPI');category=selected.category;setRange('10');renderNav();renderList();select(selected.id);$('#appError').hidden=true}catch(e){$('#appError').hidden=false;$('#appError').textContent='暫時無法讀取資料，請按「重新載入」重試。'+e.message;$('#chartTitle').textContent='資料尚未載入'}}
function renderNav(){const cats=['全部',...new Set(catalog.map(c=>c.category))];$('#categories').innerHTML=cats.map(x=>`<button data-cat="${esc(x)}" class="${x===category?'active':''}">${esc(x)}<span>${catalog.filter(c=>x==='全部'||c.category===x).length}</span></button>`).join('')+'<button data-cat="對照總覽">書中對照表<span>105</span></button>';$('#categories').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(b.dataset.cat==='對照總覽'){coverage();return}category=b.dataset.cat;$('#coverage').hidden=true;$('#workspace').hidden=false;renderNav();renderList(true)})}
function filtered(){const q=$('#search').value.toLowerCase().trim();return catalog.filter(c=>(category==='全部'||c.category===category)&&(!q||[c.title,c.note,c.pages.join(' '),c.series.join(' ')].join(' ').toLowerCase().includes(q)))}
function renderList(choose=false){const cs=filtered();$('#categoryTitle').textContent=category;$('#chartlist').innerHTML=cs.map(c=>`<button data-id="${c.id}" class="${c.id===selected?.id?'active':''}">${esc(c.title)}${c.status==='pending'?' · 待補':''}</button>`).join('');$('#chartlist').querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.id));if(choose&&cs.length)select(cs[0].id);if(!cs.length){$('#chartlist').textContent='沒有符合條件的圖表，請更換關鍵字或選擇「全部」。'}}
function select(id){selected=catalog.find(c=>c.id===id);if(!selected)return;hidden.clear();mode='default';$('#mode').value=mode;history.replaceState(null,'','#'+id);$('#workspace').hidden=false;$('#coverage').hidden=true;$('#chartlist').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.id===id));renderChart()}
function setRange(r){range=r;const all=catalog.filter(c=>c.status!=='pending').flatMap(c=>c.series.map(id=>db.series[id]).filter(Boolean));const max=all.map(s=>s.data.at(-1)?.[0]).filter(Boolean).sort().at(-1)||new Date().toISOString().slice(0,10);end=max;if(r==='book'){start='1980-01-01';end='2014-03-01'}else if(r==='all')start='1900-01-01';else start=(+end.slice(0,4)-Number(r))+end.slice(4);$('#start').value=start;$('#end').value=end;document.querySelectorAll('[data-range]').forEach(b=>b.classList.toggle('active',b.dataset.range===r))}
function seriesForChart(){const effective=mode==='default'?selected.mode:mode;let ss=selected.series.map(id=>db.series[id]).filter(Boolean);if(effective==='ratio'){if(ss.length<2)return [];const data=ratio(ss[0].data,ss[1].data).filter(([d])=>d>=start&&d<=end);return [{...ss[0],name:selected.title,unit:'%',data,color:colors[0],displayMode:'ratio'}]}
return ss.map((s,i)=>{const m=effective==='mixed'?(i===0?'yoy':'raw'):effective==='labor'?(i===0?'raw':'yoy'):effective;return {...s,data:transform(s,m,start,end),unit:m==='yoy'?'年增率 %':m==='index'?'起點=100':s.unit,color:colors[i%colors.length],displayMode:m}})}
function renderChart(){if(!selected)return;$('#chartTitle').textContent=selected.title;$('#chartNote').textContent=selected.note||'依官方公布資料重建，詳細定義與涵蓋期間見下方來源。';$('#badges').innerHTML=`<span class="badge ${selected.status==='pending'||selected.status==='proxy'?'amber':'green'}">${statusName(selected)}</span><span class="badge">PDF 第 ${selected.pages.join('、')} 頁</span>`;const valid=start<=end;shown=valid?seriesForChart():[];drawn=shown.filter(s=>!hidden.has(s.id)&&s.data.length);$('#rangeHint').textContent=range==='book'?'1980–2014 年共用視窗；不是每張原圖的精確期間。':'每條線依自身發布頻率顯示，不補齊缺值。';$('#metricCards').innerHTML=drawn.map(s=>{const r=s.data.at(-1);return `<div class="metric"><div class="metric-name">${esc(s.name)}</div><div class="metric-value" style="color:${s.color}">${short(r[1])}<small>${esc(s.unit)}</small></div><div class="metric-date">區間末筆 ${r[0]}${s.displayMode==='index'?' · 起點 '+s.data[0][0]:''}</div></div>`}).join('');$('#legend').innerHTML=shown.map(s=>`<button data-series="${esc(s.id)}" class="${hidden.has(s.id)?'off':''}" aria-pressed="${!hidden.has(s.id)}"><span class="swatch" style="background:${s.color}"></span>${esc(s.name)}${!s.data.length?'（此區間無資料）':''}</button>`).join('');$('#legend').querySelectorAll('button').forEach(b=>b.onclick=()=>{hidden.has(b.dataset.series)?hidden.delete(b.dataset.series):hidden.add(b.dataset.series);renderChart()});$('#originalPages').innerHTML=selected.pages.map(p=>`<figure><figcaption>PDF 第 ${p} 頁</figcaption><a href="book/p${p}.jpg" target="_blank"><img src="book/p${p}.jpg" loading="lazy" alt="原書 PDF 第 ${p} 頁"></a></figure>`).join('');$('#sources').innerHTML=selected.series.map(id=>{const s=db.series[id];if(!s)return '';return `<tr><td><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.name)} ↗</a><small>${esc(s.source)} · ${esc(id)}</small>${s.sourceTitle?`<small>${esc(s.sourceTitle)}</small>`:''}</td><td>${esc(s.unit)}<small>${freq[s.freq]}資料</small><small>${esc(s.sourceUnit||'')}</small></td><td>${s.data.length?s.data[0][0]+' ～ '+s.data.at(-1)[0]:'尚無資料'}<small>${s.data.length.toLocaleString()} 筆</small></td><td>${s.status==='ok'?'擷取成功':s.status==='stale'?'本次失敗，保留舊資料':'本次擷取失敗'}<small>${s.fetched?new Date(s.fetched).toLocaleDateString('zh-TW',{timeZone:'Asia/Taipei'}):'—'}</small></td></tr>`}).join('');const flat=drawn.flatMap(s=>s.data.map(([date,v])=>({date,v,name:s.name,unit:s.unit}))).sort((a,b)=>b.date.localeCompare(a.date));$('#dataRows').innerHTML=flat.slice(0,100).map(r=>`<tr><td>${r.date}</td><td>${esc(r.name)}</td><td>${fmt(r.v)}</td><td>${esc(r.unit)}</td></tr>`).join('');$('#download').disabled=!flat.length;const err=!valid?'起日必須早於或等於迄日。':selected.status==='pending'?selected.note:!drawn.length?'目前區間沒有可繪製數據，請選「全部」或開啟圖例。':null;$('#empty').hidden=!err;$('#empty').textContent=err||'';$('#plot').hidden=!!err;if(err){$('#axisInfo').textContent='';return}plot()}
let geom;
function plot(){const units=[...new Set(drawn.map(s=>s.unit))];if(units.length>2){$('#empty').hidden=false;$('#empty').textContent='目前選取的指標超過兩種單位，請改選「各自起點 = 100」或「年增率」，或透過圖例保留最多兩種單位。';$('#plot').hidden=true;$('#axisInfo').textContent='';return}$('#plot').hidden=false;const W=1040,H=430,L=90,R=units.length>1?100:35,T=35,B=48,PW=W-L-R,PH=H-T-B;const all=drawn.flatMap(s=>s.data);const xmin=Math.min(...drawn.map(s=>Date.parse(s.data[0][0]))),xmax=Math.max(...drawn.map(s=>Date.parse(s.data.at(-1)[0])));const scales=units.map(unit=>{let min=Infinity,max=-Infinity;for(const s of drawn.filter(s=>s.unit===unit))for(const [,v]of s.data){min=Math.min(min,v);max=Math.max(max,v)}let pad=(max-min)*.08||Math.abs(max)*.08||1;return {unit,min:min-pad,max:max+pad}});const x=d=>L+(Date.parse(d)-xmin)/(xmax-xmin||1)*PW;const y=(v,u)=>{const s=scales[units.indexOf(u)];return T+PH-(v-s.min)/(s.max-s.min)*PH};let svg='';for(let i=0;i<=5;i++){const yy=T+PH*i/5;svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e8eef3"/>`;scales.forEach((s,j)=>{const v=s.max-(s.max-s.min)*i/5;svg+=`<text x="${j?W-R+13:L-13}" y="${yy+4}" text-anchor="${j?'start':'end'}">${short(v)}</text>`})}for(let i=0;i<=5;i++){const xx=L+PW*i/5;const d=new Date(xmin+(xmax-xmin)*i/5).toISOString().slice(0,10);svg+=`<text x="${xx}" y="${H-13}" text-anchor="middle">${d.slice(0,7)}</text>`}scales.forEach((s,i)=>svg+=`<text x="${i?W-R:L}" y="17" text-anchor="${i?'end':'start'}">${esc(s.unit)} · ${i?'右軸':'左軸'}</text>`);drawn.forEach(s=>{let points=s.data;const d=points.map(([dt,v],i)=>(i?'L':'M')+x(dt).toFixed(2)+','+y(v,s.unit).toFixed(2)).join(' ');svg+=`<path d="${d}" fill="none" stroke="${s.color}" stroke-width="2.4" stroke-linejoin="round"/>`;if(points.length<=80)for(const [dt,v]of points)svg+=`<circle cx="${x(dt)}" cy="${y(v,s.unit)}" r="2.3" fill="${s.color}"/>`});svg+=`<line id="cross" x1="0" x2="0" y1="${T}" y2="${T+PH}" stroke="#96aabc" stroke-dasharray="4 4" visibility="hidden"/><rect id="hit" x="${L}" y="${T}" width="${PW}" height="${PH}" fill="transparent"/>`;$('#chart').innerHTML=svg;geom={L,PW,xmin,xmax};$('#axisInfo').textContent=scales.map((u,i)=>(i?'右軸：':'左軸：')+u.unit).join(' · ');const hit=$('#hit');hit.addEventListener('pointermove',hover);hit.addEventListener('pointerleave',()=>{$('#tooltip').hidden=true;$('#cross').setAttribute('visibility','hidden')});}
function hover(e){const rect=$('#chart').getBoundingClientRect();const cx=(e.clientX-rect.left)/rect.width*1040;const fraction=Math.max(0,Math.min(1,(cx-geom.L)/geom.PW));const d=new Date(geom.xmin+fraction*(geom.xmax-geom.xmin)).toISOString().slice(0,10);$('#cross').setAttribute('x1',cx);$('#cross').setAttribute('x2',cx);$('#cross').setAttribute('visibility','visible');const tooltip=$('#tooltip');tooltip.innerHTML='<strong>游標日期 '+d+'</strong>'+drawn.map(s=>{if(d<s.data[0][0]||d>s.data.at(-1)[0])return `<div>${esc(s.name)}：此日不在資料期間</div>`;const row=nearest(s.data,d);return `<div><span style="color:${s.color}">●</span> ${esc(s.name)}<br>${row[0]}　${fmt(row[1])} ${esc(s.unit)}</div>`}).join('')+'<div style="opacity:.65">各系列顯示距游標最近的觀測日</div>';tooltip.hidden=false;const w=$('#plot').clientWidth;tooltip.style.left=Math.max(0,Math.min(e.clientX-rect.left+15,w-tooltip.offsetWidth))+'px';tooltip.style.top=Math.max(0,e.clientY-rect.top-40)+'px'}
function coverage(){$('#coverage').hidden=false;$('#workspace').hidden=true;$('#categoryTitle').textContent='書中圖表對照';$('#coverageRows').innerHTML=catalog.map(c=>`<div class="coverage-row"><div><button data-id="${c.id}">${esc(c.title)}</button><small>${esc(c.category)} · PDF ${c.pages.join('、')} 頁</small></div><div><span class="badge ${c.status==='mapped'?'green':'amber'}">${statusName(c)}</span></div><p>${esc(c.note||'已連接官方歷史數據。')}</p></div>`).join('');$('#coverageRows').querySelectorAll('button').forEach(b=>b.onclick=()=>{const c=catalog.find(c=>c.id===b.dataset.id);category=c.category;renderNav();select(c.id);renderList();$('#categoryTitle').textContent=category;window.scrollTo({top:0,behavior:'smooth'})})}
$('#search').addEventListener('input',()=>{category='全部';$('#coverage').hidden=true;$('#workspace').hidden=false;renderNav();renderList(true)});document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{setRange(b.dataset.range);renderChart()});for(const id of ['start','end'])$('#'+id).onchange=()=>{start=$('#start').value;end=$('#end').value;range='custom';document.querySelectorAll('[data-range]').forEach(b=>b.classList.remove('active'));renderChart()};$('#mode').onchange=e=>{mode=e.target.value;renderChart()};$('#refresh').onclick=()=>location.reload();$('#coverageBtn').onclick=coverage;
$('#download').onclick=()=>{const cells=['date','series_id','series','value','unit','source','fetched_at'];const rows=drawn.flatMap(s=>s.data.map(([d,v])=>[d,s.id,s.name,v,s.unit,s.url,s.fetched]));const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv='\uFEFF'+[cells,...rows].map(r=>r.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${selected.title}_${start}_${end}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
// Optional structured access shares the same selection and date state as the visible controls.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_economic_chart',description:'選擇書中圖表及日期區間，更新目前可見的圖表。',inputSchema:{type:'object',properties:{chart_id:{type:'string'},start:{type:'string'},end:{type:'string'}},required:['chart_id'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const c=catalog.find(c=>c.id===input.chart_id);if(!c)throw Error('未知圖表');const a=input.start??start,b=input.end??end;const valid=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d))&&new Date(d).toISOString().slice(0,10)===d;if(!valid(a)||!valid(b)||a>b)throw Error('日期區間錯誤');category=c.category;start=a;end=b;$('#start').value=start;$('#end').value=end;range='custom';document.querySelectorAll('[data-range]').forEach(e=>e.classList.remove('active'));renderNav();select(c.id);renderList();return {chart_id:c.id,title:c.title,start,end,status:c.status,series:drawn.map(s=>({id:s.id,observations:s.data.length}))}}})).catch(()=>{})}catch{}}
init();
